func first<T: Comparable>(_ a: [T], equalTo b: T) -> Int? {
    for (i, x) in a.enumerated() where x == b { return i }
    return nil
}
first([3, 1, 4, 1, 5], equalTo: 4)  // 2
first(["a", "b", "c"], equalTo: "b") // 1

enum LoadError: Error {
    case fileMissing(String)
    case invalidFormat(line: Int)
}

func loadConfig(at url: URL) throws -> [String: String] {
    let handle = openHandle(url)
    defer { closeHandle(handle) }  // runs even if we throw

    let data = try readFile(handle)
    guard let parsed = parse(data) else { throw LoadError.invalidFormat(line: 1) }
    return parsed
}

do {
    let cfg = try loadConfig(at: URL(fileURLWithPath: "/etc/app.conf"))
    print(cfg)
} catch LoadError.fileMissing(let path) {
    print("missing: \(path)")
} catch {
    print("other error: \(error)")
}

class Person {
    var name: String
    var apartment: Apartment?      // strong
    init(name: String) { self.name = name }
    deinit { print("\(name) deinit") }
}

class Apartment {
    var unit: String
    var tenant: Person?            // strong — CYCLE
    init(unit: String) { self.unit = unit }
    deinit { print("Apartment \(unit) deinit") }
}

var ada: Person? = Person(name: "Ada")
var apt: Apartment? = Apartment(unit: "4A")
ada?.apartment = apt
apt?.tenant = ada
ada = nil; apt = nil  // NEITHER deinit runs — leaked!

func fetchUser(_ id: Int) async throws -> User {
    let (data, _) = try await URLSession.shared.data(from: URL(string: "https://api.example.com/users/\(id)")!)
    return try JSONDecoder().decode(User.self, from: data)
}

func loadProfile() async {
    do {
        let user = try await fetchUser(42)
        print(user.name)
    } catch {
        print("failed: \(error)")
    }
}

import Combine

let subject = PassthroughSubject<Int, Never>()

let cancellable = subject
    .filter { $0.isMultiple(of: 2) }
    .map { $0 * $0 }
    .sink { print($0) }   // 4, 16, 36

subject.send(2); subject.send(3); subject.send(4); subject.send(6)
